function criarPar() {
  const a = {};
  const b = {};
  a.outro = b;
  b.outro = a; // referência cíclica entre a e b
  return "par criado";
}

criarPar();
// depois desta chamada, nem "a" nem "b" têm qualquer variável que lhes
// chegue a partir de uma raiz (nem global, nem na pilha, nem em closure).
// Uma contagem de referências ingénua nunca chegaria a zero (a referencia
// b e b referencia a), mas o mark-and-sweep usado pelos motores atuais
// não depende disso: como nenhum dos dois é alcançável a partir das
// raízes, ambos são marcados como lixo e recolhidos.

const metadados = new WeakMap();

class Sessao {
  constructor(utilizador) {
    this.utilizador = utilizador;
  }
}

let sessaoAtual = new Sessao("adriano");
metadados.set(sessaoAtual, { criadaEm: Date.now(), tentativasLogin: 0 });

console.log(metadados.get(sessaoAtual).tentativasLogin); // 0

// quando a única referência forte à sessão desaparece...
sessaoAtual = null;
// ...o objeto Sessao fica elegível para recolha de lixo, e a entrada
// correspondente no WeakMap desaparece com ele - sem chamar
// metadados.delete(...) manualmente, e sem qualquer fuga de memória.

const jaProcessados = new WeakSet();

function processar(item) {
  if (jaProcessados.has(item)) {
    return; // já foi tratado, evita reprocessar
  }

  jaProcessados.add(item);
  console.log(`a processar item #${item.id}`);
}

let tarefa = { id: 1 };
processar(tarefa);
processar(tarefa); // ignorado, já está no WeakSet

tarefa = null;
// assim que "tarefa" deixar de ter outras referências, o motor pode
// recolhê-la, e a entrada correspondente desaparece do WeakSet sozinha.

class CacheDeImagem {
  #referencia;

  constructor(imagem) {
    this.#referencia = new WeakRef(imagem);
  }

  obter() {
    const imagem = this.#referencia.deref();
    if (imagem === undefined) {
      console.log("a imagem já foi recolhida, é preciso recarregar");
      return null;
    }
    return imagem;
  }
}

let imagemGrande = { largura: 4000, altura: 3000, pixels: new Uint8Array(1e7) };
const cache = new CacheDeImagem(imagemGrande);

console.log(cache.obter()); // devolve o objeto, ainda está vivo

imagemGrande = null;
// nalgum momento posterior, indeterminado, o garbage collector pode
// recolher o objeto; só a partir daí cache.obter() passa a devolver null.

const registoDeLimpeza = new FinalizationRegistry((valorDeAcompanhamento) => {
  console.log(`recurso "${valorDeAcompanhamento}" foi libertado pelo GC`);
});

function criarRecurso(nome) {
  const recurso = { nome, bufferExterno: new ArrayBuffer(1024 * 1024) };
  registoDeLimpeza.register(recurso, nome);
  return recurso;
}

let recurso = criarRecurso("ligacao-temporaria");
recurso = null;
// em algum momento, sem garantia de quando (ou se) isso acontece antes
// de o programa terminar, o motor invoca o callback registado acima.

