const registoDeAcessos = new WeakMap();

function registarAcesso(utilizador) {
  const atual = registoDeAcessos.get(utilizador) ?? 0;
  registoDeAcessos.set(utilizador, atual + 1);
}

function obterAcessos(utilizador) {
  return registoDeAcessos.get(utilizador) ?? 0;
}

const ana = { nome: "Ana" };
const bruno = { nome: "Bruno" };

registarAcesso(ana);
registarAcesso(ana);
registarAcesso(bruno);

console.log(obterAcessos(ana));   // 2
console.log(obterAcessos(bruno)); // 1

function calcularResumoAsync(documento) {
  return new Promise((resolve) => {
    console.log(`a processar "${documento.titulo}"...`);
    setTimeout(() => resolve(`resumo de ${documento.titulo}`), 100);
  });
}

const documentosEmProcessamento = new WeakSet();

async function processarDocumento(documento) {
  if (documentosEmProcessamento.has(documento)) {
    console.log("já em processamento, ignorado");
    return;
  }

  documentosEmProcessamento.add(documento);
  const resumo = await calcularResumoAsync(documento);
  documentosEmProcessamento.delete(documento);
  return resumo;
}

const relatorio = { titulo: "Relatório Anual" };
processarDocumento(relatorio);
processarDocumento(relatorio); // "já em processamento, ignorado"

function criarCacheComputado(funcaoCara) {
  const cache = new WeakMap();

  return function (entrada) {
    if (cache.has(entrada)) {
      return cache.get(entrada);
    }

    const resultado = funcaoCara(entrada);
    cache.set(entrada, resultado);
    return resultado;
  };
}

let chamadas = 0;

function somarArray(array) {
  chamadas++;
  return array.reduce((total, atual) => total + atual, 0);
}

const somarComCache = criarCacheComputado(somarArray);

const numeros = [1, 2, 3, 4, 5];

console.log(somarComCache(numeros)); // 15
console.log(somarComCache(numeros)); // 15, vindo do cache
console.log(chamadas);               // 1

console.log(somarComCache([1, 2, 3])); // 6, objeto diferente
console.log(chamadas);                 // 2

function criarRegistoDeSessoes() {
  const referencias = new Map(); // idSessao -> WeakRef(sessao)

  const registoDeLimpeza = new FinalizationRegistry((idSessao) => {
    referencias.delete(idSessao);
  });

  function registar(sessao, idSessao) {
    referencias.set(idSessao, new WeakRef(sessao));
    registoDeLimpeza.register(sessao, idSessao);
  }

  function obterAtivas() {
    const ativas = [];

    for (const [idSessao, referencia] of referencias) {
      const sessao = referencia.deref();
      if (sessao === undefined) {
        referencias.delete(idSessao);
      } else {
        ativas.push(idSessao);
      }
    }

    return ativas;
  }

  return { registar, obterAtivas };
}

const registo = criarRegistoDeSessoes();

let sessaoA = { utilizador: "ana" };
registo.registar(sessaoA, "sessao-a");

console.log(registo.obterAtivas()); // ["sessao-a"]

// tanto o callback do FinalizationRegistry como a auto-limpeza feita
// em obterAtivas() dependem de quando (ou se) o motor decide recolher
// sessaoA - não há qualquer garantia de tempo, por isso este padrão
// serve apenas para poupar memória, nunca para lógica que precise de
// correr num momento certo (ex.: fechar uma ligação de rede a tempo)
